package io.github.polestarcn.companion;
import static org.junit.Assert.*;import android.content.*;import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class EffectsBeta10Test {
 Context c;RectF b=new RectF(100,80,500,280);
 @Before public void start(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("preferences",0).edit().clear().commit();}
 @Test public void profilesAreIndependentAndFocusAxesPreserveUntouchedDefault(){AppPreferences.set(c,"fx_charge_field_range","350");AppPreferences.set(c,"fx_climate_field_range","80");AppPreferences.set(c,"fx_clean_field_range","180");AppPreferences.set(c,"fx_clean_field_focus_x","20");EffectSettings p=new EffectSettings(c);assertEquals(350,p.chargeField.range);assertEquals(80,p.climateField.range);assertEquals(180,p.cleanField.range);assertEquals(180,p.cleanField.x(b,300),.001);assertEquals(155,p.cleanField.y(b,155),.001);assertEquals(152,p.chargeField.x(b,152),.001);AppPreferences.set(c,"fx_air_direction","absorb");AppPreferences.set(c,"fx_clean_field_focus_y","75");p=new EffectSettings(c);float[] out=new float[2];new AirflowRenderer().position(b,true,3,1,p,p.cleanField,out);assertEquals(180,out[0],.001);assertEquals(230,out[1],.001);assertEquals(200,p.chargeField.count(500,200));EffectSettings.defaults(c);assertEquals(100,new EffectSettings(c).chargeField.range);assertFalse(new EffectSettings(c).cleanField.customFocus);}
 @Test public void layersAllowAllFrontOrAllBackForChargingAndAir(){for(int behind:new int[]{0,100}){for(String prefix:new String[]{"fx_charge_field_","fx_climate_field_","fx_clean_field_"})AppPreferences.set(c,prefix+"behind",""+behind);AppPreferences.set(c,"fx_direction","absorb");AppPreferences.set(c,"fx_air_direction","absorb");EffectSettings p=new EffectSettings(c);for(int layer=0;layer<2;layer++){Bitmap image=Bitmap.createBitmap(700,400,Bitmap.Config.ARGB_8888);new ChargingParticleRenderer().drawLayer(new Canvas(image),b,300,180,2,1,p,100,1,layer);assertEquals(behind==100?layer==0:layer==1,count(image)>0);image.eraseColor(0);new AirflowRenderer().drawLayer(new Canvas(image),b,true,2,1,p,EffectStateController.Mode.PURIFICATION,100,1,layer);assertEquals(behind==100?layer==0:layer==1,count(image)>0);image.recycle();}}}
 @Test public void longerTrailsDrawMoreAndSphereEdgesContainSoftAlpha(){AppPreferences.set(c,"fx_turbulence","off");int[] drawn=new int[2];int i=0;for(String length:new String[]{"10","300"}){AppPreferences.set(c,"fx_trail_length",length);Bitmap image=Bitmap.createBitmap(700,400,Bitmap.Config.ARGB_8888);new AirflowRenderer().draw(new Canvas(image),b,true,1.5f,1,new EffectSettings(c),EffectStateController.Mode.HEATING,120,1);drawn[i++]=count(image);}assertTrue(drawn[1]>drawn[0]);AppPreferences.set(c,"fx_air_shape","spheres");Bitmap image=Bitmap.createBitmap(700,400,Bitmap.Config.ARGB_8888);new AirflowRenderer().draw(new Canvas(image),b,true,1.5f,1,new EffectSettings(c),EffectStateController.Mode.COOLING,120,1);int soft=0;for(int y=0;y<400;y++)for(int x=0;x<700;x++){int a=Color.alpha(image.getPixel(x,y));if(a>0&&a<100)soft++;}assertTrue(soft>50);}
 @Test public void windowCycleIsContinuousAndStaysInsideGlassAtMaximumCoverage(){WindowGlowRenderer glow=new WindowGlowRenderer();Bitmap a=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888),z=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888);RectF full=new RectF(0,0,500,300);glow.draw(new Canvas(a),full,R.drawable.vehicle_top,0,EffectStateController.Mode.HEATING,300,1,300,10);glow.draw(new Canvas(z),full,R.drawable.vehicle_top,10,EffectStateController.Mode.HEATING,300,1,300,10);assertEquals(0,Color.alpha(z.getPixel(250,150)));assertEquals(0,Color.alpha(z.getPixel(5,5)));for(int y=0;y<300;y+=5)for(int x=0;x<500;x+=5)assertTrue(Math.abs(Color.alpha(a.getPixel(x,y))-Color.alpha(z.getPixel(x,y)))<=1);}
 int count(Bitmap b){int n=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)if(Color.alpha(b.getPixel(x,y))>0)n++;return n;}
}
